import{_ as a}from"./chunks/me3.CrD21wG6.js";import{_ as t,o as i,c as o,ae as r}from"./chunks/framework.D_sy9b7Z.js";const u=JSON.parse('{"title":"Fabio Di Nocera","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),n={name:"en/index.md"};function s(h,e,c,l,d,m){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="fabio-di-nocera" tabindex="-1">Fabio Di Nocera <a class="header-anchor" href="#fabio-di-nocera" aria-label="Permalink to &quot;Fabio Di Nocera&quot;">​</a></h1><br><br><img src="'+a+'" alt="Profile pic" class="foto-piccola"><h2 id="a-short-bio" tabindex="-1">A short bio <a class="header-anchor" href="#a-short-bio" aria-label="Permalink to &quot;A short bio&quot;">​</a></h2><p>Born in <a href="https://it.wikipedia.org/wiki/Panuozzo" target="_blank" rel="noreferrer">Gragnano</a> in 1992, raised in Castellammare di Stabia, I studied physics at University of Naples, where I earned my Bachelor and my Master degree.</p><p>During my studies, I came close to the world of <em>mathematical methods for physics</em>, in particular to the applications of differential geometry to quantum mechanics and information theory. This has brought me to a short but happy experience in research, as Ph.D. student at the Max Planck Institute for Mathematics in the Sciences.</p><p>A great use of this space is to thank once again professors Patrizia Vitale, Giuseppe Marmo and Jürgen Jost for the insightful and caring supervision.</p><p>I have taught and talked about maths and sciences (to the boredom of most) for several years now. Since I defended my Ph.D. thesis, in April 2024, I decided to make it my job.</p><h2 id="what-can-one-find-on-this-website" tabindex="-1">What can one find on this website? <a class="header-anchor" href="#what-can-one-find-on-this-website" aria-label="Permalink to &quot;What can one find on this website?&quot;">​</a></h2><p>Several things.</p><p>The <a href="./ricerca.html">research</a> page contains the output of my scientific work in the years 2020-2024. Chances are you can skip it.</p><p>In the <a href="./comunicazione.html">communication</a> page there are some articles. These represent an attempt (perhaps clumsy) to hold together different things: science journalism in the strict sense, but also other, more peripheral aspects, such as excursions into the history of science or technology, or discussions of the way we perceive science and mathematics, the way we talk about them and the way we teach them.</p><p>The <a href="./didattica.html">teaching</a> page is an experiment. I would like to create some <em>thematic pages</em> dedicated to various topics in mathematics and physics, with the idea of explaining them by taking advantage of the possibility of creating explorable models, animations and interactive graphs. It’s all one big <em>work in progress</em>, with no clear deadline.</p><h2 id="contacts-and-links" tabindex="-1">Contacts and links <a class="header-anchor" href="#contacts-and-links" aria-label="Permalink to &quot;Contacts and links&quot;">​</a></h2><ul><li><strong>Email:</strong> <a href="mailto:fabiodncr@gmail.com" target="_blank" rel="noreferrer">fabiodncr@gmail.com</a></li><li><a href="https://github.com/Fabiodncr" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://www.linkedin.com/in/fabio-di-nocera-647123180" target="_blank" rel="noreferrer">Linkedin</a></li><li><a href="https://scholar.google.com/citations?view_op=list_works&amp;hl=it&amp;user=f4tI0xcAAAAJ" target="_blank" rel="noreferrer">Google Scholar</a></li></ul>',16)])])}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
